        if let value = filter0 {
            guard value.count == 32 else { throw WrapperError.encodingFailed("bytes32 length") }
            guard let topic = ABI.Element.Event.encodeTopic(input: event.inputs[0], value: value) else { throw WrapperError.encodingFailed("ReleaseRequested(bytes32,uint64)") }
            topics.append(topic)
        } else { topics.append(nil) }
        return topics
    }

    /// Decodes a `ReleaseRequested(bytes32,uint64)` log.
    public static func decodeReleaseRequestedEvent(_ log: EventLog) throws -> ReleaseRequestedEvent {
        let event = try _eventReleaseRequested()
        guard log.topics.count == 2 else { throw WrapperError.eventMismatch }
        guard log.topics.first == event.topic else { throw WrapperError.eventMismatch }
        guard let decoded = ABIDecoder.decode(types: event.inputs.filter { !$0.indexed }.map { $0.type }, data: log.data) else { throw WrapperError.invalidValue("ReleaseRequested(bytes32,uint64)") }
        let topic0 = log.topics[1]
        guard topic0.count == 32 else { throw WrapperError.invalidValue("event topic 0") }
        guard let raw0 = ABIDecoder.decode(types: [event.inputs[0].type], data: topic0)?.first else { throw WrapperError.invalidValue("event field 0") }
        let value0 = try _cast(raw0, as: Data.self)
        let value1 = try _cast(decoded[0], as: BigUInt.self)
        return ReleaseRequestedEvent(marketId: value0, unlockBlock: value1)
    }

    /// A decoded custom ABI error.
    public enum DecodedCustomError {
    }

    /// Decodes a custom revert payload, or returns nil for an unknown selector.
    public static func decodeCustomError(_ data: Data) throws -> DecodedCustomError? {
        guard data.count >= 4 else { throw WrapperError.invalidValue("error selector") }
        return nil
    }
}
